-- ============================== 20261031000001_content_and_lead_management.sql ==============================

-- Phase 1: stack content (modules, lessons), lesson file storage, reordering, lead assignment.

-- ---------------------------------------------------------------- helpers

-- Students keep access to a stack's content while active and after completing it (not after withdrawing).
create function public.is_member_of(p_stack_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.stack_members m
    where m.user_id = (select auth.uid()) and m.stack_id = p_stack_id and m.status in ('active', 'completed')
  );
$$;

-- ---------------------------------------------------------------- tables

create type public.lesson_type as enum ('video', 'pdf', 'text');

create table public.modules (
  id uuid primary key default gen_random_uuid(),
  stack_id uuid not null references public.stacks (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 2 and 160),
  description text check (description is null or char_length(description) <= 2000),
  order_index integer not null default 0,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index modules_stack_order_idx on public.modules (stack_id, order_index);

create table public.lessons (
  id uuid primary key default gen_random_uuid(),
  module_id uuid not null references public.modules (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 2 and 160),
  description text check (description is null or char_length(description) <= 2000),
  lesson_type public.lesson_type not null,
  content_url text check (content_url is null or content_url ~* '^https?://\S+$'),
  content_path text check (content_path is null or char_length(content_path) <= 500),
  content_text text check (content_text is null or char_length(content_text) <= 50000),
  duration_minutes integer check (duration_minutes is null or duration_minutes between 1 and 1000),
  order_index integer not null default 0,
  is_required boolean not null default true,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- text lessons carry text; video and pdf lessons carry exactly one of an external link or an uploaded file
  constraint lesson_shape_matches_type check (
    (lesson_type = 'text' and content_url is null and content_path is null)
    or (lesson_type <> 'text' and content_text is null and not (content_url is not null and content_path is not null))
  ),
  -- drafts may be incomplete; a published lesson must have its content
  constraint published_lesson_has_content check (
    not is_published or (
      case when lesson_type = 'text' then content_text is not null and btrim(content_text) <> ''
           else content_url is not null or content_path is not null end
    )
  )
);
create index lessons_module_order_idx on public.lessons (module_id, order_index);

create trigger modules_touch_updated_at before update on public.modules
  for each row execute function public.touch_updated_at();
create trigger lessons_touch_updated_at before update on public.lessons
  for each row execute function public.touch_updated_at();

-- New rows go to the end unless an explicit position is given.
create function public.set_module_order() returns trigger language plpgsql as $$
begin
  if new.order_index = 0 then
    select coalesce(max(order_index), 0) + 1 into new.order_index from public.modules where stack_id = new.stack_id;
  end if;
  return new;
end $$;
create trigger modules_set_order before insert on public.modules
  for each row execute function public.set_module_order();

create function public.set_lesson_order() returns trigger language plpgsql as $$
begin
  if new.order_index = 0 then
    select coalesce(max(order_index), 0) + 1 into new.order_index from public.lessons where module_id = new.module_id;
  end if;
  return new;
end $$;
create trigger lessons_set_order before insert on public.lessons
  for each row execute function public.set_lesson_order();

-- ---------------------------------------------------------------- more helpers (need the tables above)

create function public.module_stack_id(p_module_id uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select m.stack_id from public.modules m where m.id = p_module_id;
$$;

create function public.module_visible_to_member(p_module_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.modules m
    where m.id = p_module_id and m.is_published and public.is_member_of(m.stack_id)
  );
$$;

-- ---------------------------------------------------------------- RLS

alter table public.modules enable row level security;
alter table public.lessons enable row level security;

create policy "members read published modules" on public.modules for select to authenticated
  using (is_published and public.is_member_of(stack_id));
create policy "leads manage their modules" on public.modules for all to authenticated
  using (public.is_lead_of(stack_id)) with check (public.is_lead_of(stack_id));
create policy "admin manages modules" on public.modules for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy "members read published lessons" on public.lessons for select to authenticated
  using (is_published and public.module_visible_to_member(module_id));
create policy "leads manage their lessons" on public.lessons for all to authenticated
  using (public.is_lead_of(public.module_stack_id(module_id)))
  with check (public.is_lead_of(public.module_stack_id(module_id)));
create policy "admin manages lessons" on public.lessons for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

revoke all on public.modules, public.lessons from anon;

-- ---------------------------------------------------------------- reordering

create function public.reorder_modules(p_stack_id uuid, p_ids uuid[]) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not (public.is_admin() or public.is_lead_of(p_stack_id)) then
    raise exception 'Not allowed to reorder this stack' using errcode = 'insufficient_privilege';
  end if;
  if coalesce(array_length(p_ids, 1), 0) <> (select count(*) from public.modules where stack_id = p_stack_id)
     or (select count(distinct x) from unnest(p_ids) x) <> coalesce(array_length(p_ids, 1), 0)
     or exists (select 1 from unnest(p_ids) x where not exists (
          select 1 from public.modules m where m.id = x and m.stack_id = p_stack_id)) then
    raise exception 'The list must contain every module of the stack exactly once' using errcode = 'check_violation';
  end if;
  update public.modules m set order_index = o.ord
  from unnest(p_ids) with ordinality as o (id, ord)
  where m.id = o.id;
end $$;

create function public.reorder_lessons(p_module_id uuid, p_ids uuid[]) returns void
language plpgsql security definer set search_path = '' as $$
declare v_stack uuid := public.module_stack_id(p_module_id);
begin
  if v_stack is null or not (public.is_admin() or public.is_lead_of(v_stack)) then
    raise exception 'Not allowed to reorder this module' using errcode = 'insufficient_privilege';
  end if;
  if coalesce(array_length(p_ids, 1), 0) <> (select count(*) from public.lessons where module_id = p_module_id)
     or (select count(distinct x) from unnest(p_ids) x) <> coalesce(array_length(p_ids, 1), 0)
     or exists (select 1 from unnest(p_ids) x where not exists (
          select 1 from public.lessons l where l.id = x and l.module_id = p_module_id)) then
    raise exception 'The list must contain every lesson of the module exactly once' using errcode = 'check_violation';
  end if;
  update public.lessons l set order_index = o.ord
  from unnest(p_ids) with ordinality as o (id, ord)
  where l.id = o.id;
end $$;

-- ---------------------------------------------------------------- lead assignment

-- An email that already belongs to a lead is assigned directly (returns null: no invitation email needed).
create or replace function public.create_lead_invitation(p_email text, p_stack_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_email text := lower(trim(p_email));
  v_id uuid;
  v_user uuid;
  v_existing public.user_role;
begin
  if not public.is_admin() then raise exception 'Admins only' using errcode = 'insufficient_privilege'; end if;
  if not exists (select 1 from public.stacks where id = p_stack_id and is_active) then
    raise exception 'Unknown or inactive stack' using errcode = 'foreign_key_violation';
  end if;
  select id, role into v_user, v_existing from public.profiles where lower(email) = v_email;
  if v_existing is not null and v_existing <> 'stack_lead' then
    raise exception 'This email already belongs to a % account', v_existing using errcode = 'check_violation';
  end if;
  if v_existing = 'stack_lead' then
    insert into public.stack_leads (user_id, stack_id) values (v_user, p_stack_id) on conflict do nothing;
    perform public.write_audit('assign_lead', 'stack_lead', v_user::text, jsonb_build_object('stack_id', p_stack_id));
    return null;
  end if;
  insert into public.invitations (email, role, stack_id, invited_by)
  values (v_email, 'stack_lead', p_stack_id, (select auth.uid()))
  returning id into v_id;
  perform public.write_audit('invite_lead', 'invitation', v_id::text, jsonb_build_object('email', v_email, 'stack_id', p_stack_id));
  return v_id;
end $$;

create function public.remove_lead_from_stack(p_user_id uuid, p_stack_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Admins only' using errcode = 'insufficient_privilege'; end if;
  delete from public.stack_leads where user_id = p_user_id and stack_id = p_stack_id;
  perform public.write_audit('remove_lead', 'stack_lead', p_user_id::text, jsonb_build_object('stack_id', p_stack_id));
end $$;

-- ---------------------------------------------------------------- lesson file storage
-- Path convention: <stack_id>/<module_id>/<file>. The first folder decides who may read and write.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('lesson-media', 'lesson-media', false, 104857600, array['application/pdf', 'video/mp4', 'video/webm'])
on conflict (id) do nothing;

create function public.storage_stack_id(p_name text) returns uuid
language sql immutable set search_path = '' as $$
  select case
    when split_part(p_name, '/', 1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then split_part(p_name, '/', 1)::uuid
  end;
$$;

create policy "lesson media: read" on storage.objects for select to authenticated
  using (bucket_id = 'lesson-media' and (
    public.is_admin() or public.is_lead_of(public.storage_stack_id(name)) or public.is_member_of(public.storage_stack_id(name))
  ));
create policy "lesson media: upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'lesson-media' and (public.is_admin() or public.is_lead_of(public.storage_stack_id(name))));
create policy "lesson media: replace" on storage.objects for update to authenticated
  using (bucket_id = 'lesson-media' and (public.is_admin() or public.is_lead_of(public.storage_stack_id(name))));
create policy "lesson media: delete" on storage.objects for delete to authenticated
  using (bucket_id = 'lesson-media' and (public.is_admin() or public.is_lead_of(public.storage_stack_id(name))));

-- ---------------------------------------------------------------- privileges for the new functions
revoke execute on function
  public.is_member_of(uuid), public.module_stack_id(uuid), public.module_visible_to_member(uuid),
  public.reorder_modules(uuid, uuid[]), public.reorder_lessons(uuid, uuid[]),
  public.create_lead_invitation(text, uuid), public.remove_lead_from_stack(uuid, uuid), public.storage_stack_id(text)
from public, anon;
grant execute on function
  public.is_member_of(uuid), public.module_stack_id(uuid), public.module_visible_to_member(uuid),
  public.reorder_modules(uuid, uuid[]), public.reorder_lessons(uuid, uuid[]),
  public.create_lead_invitation(text, uuid), public.remove_lead_from_stack(uuid, uuid), public.storage_stack_id(text)
to authenticated;

-- ============================== 20261101000001_learning.sql ==============================

-- Phase 2: the student learning path.
-- Lesson completion, assignments (auto-graded quizzes and lead-graded submissions), module unlocking,
-- server-computed progress, class roster. Quiz answer keys and grading never reach the browser.

create type public.assignment_type as enum ('quiz', 'submission');
create type public.submission_status as enum ('submitted', 'graded', 'needs_resubmission');

-- ---------------------------------------------------------------- tables

create table public.lesson_completions (
  user_id uuid not null references public.profiles (id) on delete cascade,
  lesson_id uuid not null references public.lessons (id) on delete cascade,
  completed_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);
create index lesson_completions_lesson_idx on public.lesson_completions (lesson_id);

-- One assignment per module.
create table public.assignments (
  id uuid primary key default gen_random_uuid(),
  module_id uuid not null unique references public.modules (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 2 and 160),
  type public.assignment_type not null,
  instructions text check (instructions is null or char_length(instructions) <= 10000),
  max_score integer not null default 100 check (max_score between 1 and 1000),
  pass_mark integer not null default 60 check (pass_mark between 1 and 100), -- percent of max_score
  max_attempts integer check (max_attempts is null or max_attempts between 1 and 20), -- null = unlimited
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint published_submission_has_instructions check (
    not is_published or type = 'quiz' or (instructions is not null and btrim(instructions) <> '')
  )
);
create trigger assignments_touch_updated_at before update on public.assignments
  for each row execute function public.touch_updated_at();

create table public.assignment_questions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments (id) on delete cascade,
  prompt text not null check (char_length(btrim(prompt)) between 1 and 1000),
  options jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) between 2 and 6),
  points integer not null default 1 check (points between 1 and 100),
  order_index integer not null default 0
);
create index assignment_questions_assignment_idx on public.assignment_questions (assignment_id, order_index);

-- Kept apart from the questions so students can never read the correct answers.
create table public.assignment_answer_keys (
  question_id uuid primary key references public.assignment_questions (id) on delete cascade,
  correct_index integer not null check (correct_index >= 0)
);

create table public.assignment_submissions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  attempt integer not null,
  content_text text check (content_text is null or char_length(content_text) <= 20000),
  content_url text check (content_url is null or content_url ~* '^https?://\S+$'),
  file_path text check (file_path is null or char_length(file_path) <= 500),
  answers jsonb,
  status public.submission_status not null default 'submitted',
  score integer check (score is null or score >= 0),
  feedback text check (feedback is null or char_length(feedback) <= 5000),
  graded_by uuid references public.profiles (id) on delete set null,
  graded_at timestamptz,
  submitted_at timestamptz not null default now(),
  unique (assignment_id, user_id, attempt)
);
create index assignment_submissions_user_idx on public.assignment_submissions (user_id);
create index assignment_submissions_status_idx on public.assignment_submissions (assignment_id, status);

-- ---------------------------------------------------------------- helpers (security definer)

create function public.is_active_member_of(p_stack_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.stack_members m
    where m.user_id = (select auth.uid()) and m.stack_id = p_stack_id and m.status = 'active'
  );
$$;

create function public.assignment_module_id(p_assignment_id uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select a.module_id from public.assignments a where a.id = p_assignment_id;
$$;

create function public.assignment_stack_id(p_assignment_id uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select m.stack_id from public.assignments a join public.modules m on m.id = a.module_id where a.id = p_assignment_id;
$$;

create function public.assignment_passed(p_user uuid, p_assignment_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.assignments a
    join public.assignment_submissions s on s.assignment_id = a.id
    where a.id = p_assignment_id and s.user_id = p_user and s.status = 'graded'
      and s.score is not null and s.score * 100 >= a.pass_mark * a.max_score
  );
$$;

-- A module is complete when every required published lesson is done and its published assignment is passed.
create function public.module_is_complete(p_user uuid, p_module_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select
    not exists (
      select 1 from public.lessons l
      where l.module_id = p_module_id and l.is_published and l.is_required
        and not exists (select 1 from public.lesson_completions c where c.user_id = p_user and c.lesson_id = l.id)
    )
    and not exists (
      select 1 from public.assignments a
      where a.module_id = p_module_id and a.is_published and not public.assignment_passed(p_user, a.id)
    );
$$;

-- Modules unlock in order: every earlier published module of the stack must be complete.
-- Students who completed the stack keep everything unlocked.
create function public.module_is_unlocked(p_user uuid, p_module_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select
    exists (
      select 1 from public.modules cur
      join public.stack_members sm on sm.stack_id = cur.stack_id and sm.user_id = p_user and sm.status = 'completed'
      where cur.id = p_module_id
    )
    or not exists (
      select 1 from public.modules cur
      join public.modules prev on prev.stack_id = cur.stack_id and prev.is_published and prev.order_index < cur.order_index
      where cur.id = p_module_id and not public.module_is_complete(p_user, prev.id)
    );
$$;

create function public.module_open_to_me(p_module_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.module_visible_to_member(p_module_id) and public.module_is_unlocked((select auth.uid()), p_module_id);
$$;

-- ---------------------------------------------------------------- RLS

alter table public.lesson_completions enable row level security;
alter table public.assignments enable row level security;
alter table public.assignment_questions enable row level security;
alter table public.assignment_answer_keys enable row level security;
alter table public.assignment_submissions enable row level security;

-- Locked modules really are locked: their lessons are not even readable until unlocked.
drop policy "members read published lessons" on public.lessons;
create policy "members read unlocked published lessons" on public.lessons for select to authenticated
  using (is_published and public.module_open_to_me(module_id));

create policy "own completions" on public.lesson_completions for select to authenticated using (user_id = (select auth.uid()));
create policy "leads read their students' completions" on public.lesson_completions for select to authenticated
  using (public.leads_student(user_id));
create policy "admin reads completions" on public.lesson_completions for select to authenticated using (public.is_admin());

create policy "members read open published assignments" on public.assignments for select to authenticated
  using (is_published and public.module_open_to_me(module_id));
create policy "leads manage their assignments" on public.assignments for all to authenticated
  using (public.is_lead_of(public.module_stack_id(module_id))) with check (public.is_lead_of(public.module_stack_id(module_id)));
create policy "admin manages assignments" on public.assignments for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy "members read questions" on public.assignment_questions for select to authenticated
  using (exists (select 1 from public.assignments a where a.id = assignment_id));
create policy "leads manage their questions" on public.assignment_questions for all to authenticated
  using (public.is_lead_of(public.assignment_stack_id(assignment_id))) with check (public.is_lead_of(public.assignment_stack_id(assignment_id)));
create policy "admin manages questions" on public.assignment_questions for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy "leads read answer keys" on public.assignment_answer_keys for select to authenticated
  using (public.is_lead_of(public.assignment_stack_id((select q.assignment_id from public.assignment_questions q where q.id = question_id))));
create policy "admin reads answer keys" on public.assignment_answer_keys for select to authenticated using (public.is_admin());

create policy "own submissions" on public.assignment_submissions for select to authenticated using (user_id = (select auth.uid()));
create policy "leads read their submissions" on public.assignment_submissions for select to authenticated
  using (public.is_lead_of(public.assignment_stack_id(assignment_id)));
create policy "admin reads submissions" on public.assignment_submissions for select to authenticated using (public.is_admin());

revoke all on public.lesson_completions, public.assignments, public.assignment_questions,
  public.assignment_answer_keys, public.assignment_submissions from anon;
-- Keys and submissions are written only through the functions below.
revoke insert, update, delete on public.assignment_answer_keys, public.assignment_submissions, public.lesson_completions from authenticated;

-- ---------------------------------------------------------------- student actions

create function public.complete_lesson(p_lesson_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_module uuid; v_stack uuid; v_uid uuid := (select auth.uid());
begin
  select l.module_id, m.stack_id into v_module, v_stack
  from public.lessons l join public.modules m on m.id = l.module_id
  where l.id = p_lesson_id and l.is_published and m.is_published;
  if v_module is null then raise exception 'This lesson is not available' using errcode = 'no_data_found'; end if;
  if not public.is_active_member_of(v_stack) then
    raise exception 'You are not an active member of this stack' using errcode = 'insufficient_privilege';
  end if;
  if not public.module_is_unlocked(v_uid, v_module) then
    raise exception 'Complete the previous module first' using errcode = 'check_violation';
  end if;
  insert into public.lesson_completions (user_id, lesson_id) values (v_uid, p_lesson_id) on conflict do nothing;
end $$;

-- Shared checks for both assignment types. Returns the next attempt number.
create function public.begin_attempt(p_assignment_id uuid, p_type public.assignment_type) returns integer
language plpgsql security definer set search_path = '' as $$
declare a public.assignments; v_uid uuid := (select auth.uid()); v_used integer;
begin
  select * into a from public.assignments where id = p_assignment_id and is_published and type = p_type;
  if not found then raise exception 'This assignment is not available' using errcode = 'no_data_found'; end if;
  if not public.is_active_member_of(public.assignment_stack_id(a.id)) then
    raise exception 'You are not an active member of this stack' using errcode = 'insufficient_privilege';
  end if;
  if not public.module_is_unlocked(v_uid, a.module_id) then
    raise exception 'Complete the previous module first' using errcode = 'check_violation';
  end if;
  if public.assignment_passed(v_uid, a.id) then
    raise exception 'You have already passed this assignment' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.assignment_submissions s where s.assignment_id = a.id and s.user_id = v_uid and s.status = 'submitted') then
    raise exception 'Your previous submission is still waiting to be reviewed' using errcode = 'check_violation';
  end if;
  select count(*) into v_used from public.assignment_submissions where assignment_id = a.id and user_id = v_uid;
  if a.max_attempts is not null and v_used >= a.max_attempts then
    raise exception 'You have used all attempts for this assignment' using errcode = 'check_violation';
  end if;
  return v_used + 1;
end $$;

-- Grades a quiz on the server. Returns {score, max_score, passed}; correct answers are never exposed.
create function public.submit_quiz(p_assignment_id uuid, p_answers integer[]) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  a public.assignments; v_attempt integer; v_total integer; v_earned integer; v_score integer; v_count integer;
begin
  v_attempt := public.begin_attempt(p_assignment_id, 'quiz');
  select * into a from public.assignments where id = p_assignment_id;
  select count(*), coalesce(sum(points), 0) into v_count, v_total from public.assignment_questions where assignment_id = a.id;
  if v_count = 0 then raise exception 'This quiz has no questions' using errcode = 'check_violation'; end if;
  if coalesce(array_length(p_answers, 1), 0) <> v_count then
    raise exception 'Answer every question before submitting' using errcode = 'check_violation';
  end if;
  select coalesce(sum(q.points), 0) into v_earned
  from (select id, points, row_number() over (order by order_index, id) as n from public.assignment_questions where assignment_id = a.id) q
  join public.assignment_answer_keys k on k.question_id = q.id
  where p_answers[q.n] = k.correct_index;
  v_score := round(v_earned::numeric * a.max_score / v_total);
  insert into public.assignment_submissions (assignment_id, user_id, attempt, answers, status, score, graded_at)
  values (a.id, (select auth.uid()), v_attempt, to_jsonb(p_answers), 'graded', v_score, now());
  return jsonb_build_object('score', v_score, 'max_score', a.max_score, 'passed', v_score * 100 >= a.pass_mark * a.max_score);
end $$;

create function public.submit_assignment(p_assignment_id uuid, p_text text, p_url text, p_file_path text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_attempt integer; v_id uuid; v_uid uuid := (select auth.uid());
begin
  if coalesce(btrim(p_text), '') = '' and coalesce(btrim(p_url), '') = '' and coalesce(p_file_path, '') = '' then
    raise exception 'Add your answer, a link or a file' using errcode = 'check_violation';
  end if;
  v_attempt := public.begin_attempt(p_assignment_id, 'submission');
  if p_file_path is not null and p_file_path not like public.assignment_stack_id(p_assignment_id)::text || '/' || v_uid::text || '/%' then
    raise exception 'That file does not belong to you' using errcode = 'insufficient_privilege';
  end if;
  insert into public.assignment_submissions (assignment_id, user_id, attempt, content_text, content_url, file_path)
  values (p_assignment_id, v_uid, v_attempt, nullif(btrim(p_text), ''), nullif(btrim(p_url), ''), p_file_path)
  returning id into v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------- lead actions

create function public.grade_submission(p_submission_id uuid, p_score integer, p_feedback text, p_request_resubmission boolean default false)
returns void
language plpgsql security definer set search_path = '' as $$
declare s public.assignment_submissions; a public.assignments;
begin
  select * into s from public.assignment_submissions where id = p_submission_id for update;
  if not found then raise exception 'Submission not found' using errcode = 'no_data_found'; end if;
  select * into a from public.assignments where id = s.assignment_id;
  if not (public.is_admin() or public.is_lead_of(public.assignment_stack_id(a.id))) then
    raise exception 'Not allowed to grade this submission' using errcode = 'insufficient_privilege';
  end if;
  if a.type <> 'submission' then raise exception 'Quizzes are graded automatically' using errcode = 'check_violation'; end if;
  if s.status <> 'submitted' then raise exception 'This submission was already reviewed' using errcode = 'check_violation'; end if;
  if p_request_resubmission then
    update public.assignment_submissions
    set status = 'needs_resubmission', feedback = nullif(btrim(p_feedback), ''), graded_by = (select auth.uid()), graded_at = now()
    where id = s.id;
  else
    if p_score is null or p_score < 0 or p_score > a.max_score then
      raise exception 'The score must be between 0 and %', a.max_score using errcode = 'check_violation';
    end if;
    update public.assignment_submissions
    set status = 'graded', score = p_score, feedback = nullif(btrim(p_feedback), ''), graded_by = (select auth.uid()), graded_at = now()
    where id = s.id;
  end if;
end $$;

-- Replaces a quiz's questions and answer keys atomically. p_questions: [{prompt, options[], correct_index, points}]
create function public.save_quiz(p_assignment_id uuid, p_questions jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare q jsonb; v_id uuid; v_n integer := 0;
begin
  if not (public.is_admin() or public.is_lead_of(public.assignment_stack_id(p_assignment_id))) then
    raise exception 'Not allowed to edit this quiz' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.assignments where id = p_assignment_id and type = 'quiz') then
    raise exception 'This assignment is not a quiz' using errcode = 'check_violation';
  end if;
  if jsonb_typeof(p_questions) <> 'array' then raise exception 'Questions must be a list' using errcode = 'check_violation'; end if;
  if exists (select 1 from public.assignments where id = p_assignment_id and is_published) and jsonb_array_length(p_questions) = 0 then
    raise exception 'A published quiz needs at least one question' using errcode = 'check_violation';
  end if;
  delete from public.assignment_questions where assignment_id = p_assignment_id;
  for q in select * from jsonb_array_elements(p_questions) loop
    v_n := v_n + 1;
    if (q ->> 'correct_index')::integer >= jsonb_array_length(q -> 'options') or (q ->> 'correct_index')::integer < 0 then
      raise exception 'Question % has no valid correct answer', v_n using errcode = 'check_violation';
    end if;
    insert into public.assignment_questions (assignment_id, prompt, options, points, order_index)
    values (p_assignment_id, q ->> 'prompt', q -> 'options', coalesce((q ->> 'points')::integer, 1), v_n)
    returning id into v_id;
    insert into public.assignment_answer_keys (question_id, correct_index) values (v_id, (q ->> 'correct_index')::integer);
  end loop;
end $$;

create function public.ensure_quiz_has_questions() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.is_published and new.type = 'quiz'
     and not exists (select 1 from public.assignment_questions where assignment_id = new.id) then
    raise exception 'Add at least one question before publishing the quiz' using errcode = 'check_violation';
  end if;
  return new;
end $$;
create trigger assignments_quiz_needs_questions before insert or update of is_published, type on public.assignments
  for each row execute function public.ensure_quiz_has_questions();

-- ---------------------------------------------------------------- progress

create type public.progress_summary as (
  lessons_total integer, lessons_done integer,
  assignments_total integer, assignments_passed integer,
  assignment_pct numeric, exam_pct numeric, overall integer
);

-- Weighting (PRD): lessons 40%, assignments 30%, final exam 30%. The exam arrives in Phase 3 (0 until then).
create function public.progress_for(p_user uuid, p_stack_id uuid) returns public.progress_summary
language plpgsql stable security definer set search_path = '' as $$
declare r public.progress_summary;
begin
  select count(*), count(c.lesson_id) into r.lessons_total, r.lessons_done
  from public.lessons l
  join public.modules m on m.id = l.module_id and m.stack_id = p_stack_id and m.is_published
  left join public.lesson_completions c on c.lesson_id = l.id and c.user_id = p_user
  where l.is_published and l.is_required;

  select count(*), count(*) filter (where public.assignment_passed(p_user, a.id)),
         coalesce(avg(coalesce((
           select max(s.score) from public.assignment_submissions s
           where s.assignment_id = a.id and s.user_id = p_user and s.status = 'graded'), 0)::numeric / a.max_score), 0)
  into r.assignments_total, r.assignments_passed, r.assignment_pct
  from public.assignments a
  join public.modules m on m.id = a.module_id and m.stack_id = p_stack_id and m.is_published
  where a.is_published;

  r.exam_pct := 0;
  r.overall := round(
    40 * case when r.lessons_total = 0 then 0 else r.lessons_done::numeric / r.lessons_total end
    + 30 * r.assignment_pct + 30 * r.exam_pct)::integer;
  return r;
end $$;

-- The signed-in student's progress in their current (or most recent completed) stack.
create function public.my_progress() returns public.progress_summary
language sql stable security definer set search_path = '' as $$
  select public.progress_for((select auth.uid()), m.stack_id)
  from public.stack_members m
  where m.user_id = (select auth.uid()) and m.status in ('active', 'completed')
  order by (m.status = 'active') desc, m.joined_at desc
  limit 1;
$$;

-- Per-module state for the signed-in student (the server decides what is locked or complete).
create function public.my_modules() returns table (
  module_id uuid, unlocked boolean, complete boolean,
  lessons_total integer, lessons_done integer,
  assignment_id uuid, assignment_passed boolean, attempts_used integer, best_score integer
)
language sql stable security definer set search_path = '' as $$
  with me as (
    select m.stack_id from public.stack_members m
    where m.user_id = (select auth.uid()) and m.status in ('active', 'completed')
    order by (m.status = 'active') desc, m.joined_at desc limit 1
  )
  select md.id,
    public.module_is_unlocked((select auth.uid()), md.id),
    public.module_is_complete((select auth.uid()), md.id),
    (select count(*)::integer from public.lessons l where l.module_id = md.id and l.is_published and l.is_required),
    (select count(*)::integer from public.lessons l join public.lesson_completions c on c.lesson_id = l.id and c.user_id = (select auth.uid())
       where l.module_id = md.id and l.is_published and l.is_required),
    a.id,
    case when a.id is null then null else public.assignment_passed((select auth.uid()), a.id) end,
    (select count(*)::integer from public.assignment_submissions s where s.assignment_id = a.id and s.user_id = (select auth.uid())),
    (select max(s.score) from public.assignment_submissions s where s.assignment_id = a.id and s.user_id = (select auth.uid()) and s.status = 'graded')
  from public.modules md
  join me on me.stack_id = md.stack_id
  left join public.assignments a on a.module_id = md.id and a.is_published
  where md.is_published
  order by md.order_index;
$$;

-- Class roster with progress, for the stack's leads and admins.
create function public.stack_roster(p_stack_id uuid) returns table (
  user_id uuid, full_name text, email text, phone text, status public.member_status, joined_at timestamptz,
  lessons_done integer, lessons_total integer, assignments_passed integer, assignments_total integer,
  overall integer, last_activity timestamptz
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (public.is_admin() or public.is_lead_of(p_stack_id)) then
    raise exception 'Not allowed to view this roster' using errcode = 'insufficient_privilege';
  end if;
  return query
  select p.id, p.full_name, p.email, p.phone, m.status, m.joined_at,
         pr.lessons_done, pr.lessons_total, pr.assignments_passed, pr.assignments_total, pr.overall,
         greatest(
           (select max(c.completed_at) from public.lesson_completions c where c.user_id = p.id),
           (select max(s.submitted_at) from public.assignment_submissions s where s.user_id = p.id)
         )
  from public.stack_members m
  join public.profiles p on p.id = m.user_id
  cross join lateral public.progress_for(p.id, m.stack_id) pr
  where m.stack_id = p_stack_id and m.status in ('active', 'completed')
  order by p.full_name nulls last, p.email;
end $$;

-- ---------------------------------------------------------------- storage

-- Students may only read files of lessons they can currently open (the subquery obeys the lessons RLS).
drop policy "lesson media: read" on storage.objects;
create policy "lesson media: read" on storage.objects for select to authenticated
  using (bucket_id = 'lesson-media' and (
    public.is_admin() or public.is_lead_of(public.storage_stack_id(name))
    or exists (select 1 from public.lessons l where l.content_path = name)
  ));

-- Submission files live at <stack_id>/<student_id>/<assignment_id>/<file>.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('submissions', 'submissions', false, 26214400,
  array['application/pdf', 'application/zip', 'image/png', 'image/jpeg', 'text/plain'])
on conflict (id) do nothing;

create policy "submissions: students upload to their own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'submissions'
    and split_part(name, '/', 2) = (select auth.uid())::text
    and public.is_active_member_of(public.storage_stack_id(name)));
create policy "submissions: read" on storage.objects for select to authenticated
  using (bucket_id = 'submissions' and (
    split_part(name, '/', 2) = (select auth.uid())::text
    or public.is_admin() or public.is_lead_of(public.storage_stack_id(name))));
create policy "submissions: students remove their own files" on storage.objects for delete to authenticated
  using (bucket_id = 'submissions' and split_part(name, '/', 2) = (select auth.uid())::text);

-- ---------------------------------------------------------------- privileges
revoke execute on function
  public.is_active_member_of(uuid), public.assignment_module_id(uuid), public.assignment_stack_id(uuid),
  public.assignment_passed(uuid, uuid), public.module_is_complete(uuid, uuid), public.module_is_unlocked(uuid, uuid),
  public.module_open_to_me(uuid), public.complete_lesson(uuid), public.begin_attempt(uuid, public.assignment_type),
  public.submit_quiz(uuid, integer[]), public.submit_assignment(uuid, text, text, text),
  public.grade_submission(uuid, integer, text, boolean), public.save_quiz(uuid, jsonb),
  public.progress_for(uuid, uuid), public.my_progress(), public.my_modules(), public.stack_roster(uuid)
from public, anon;
grant execute on function
  public.is_active_member_of(uuid), public.assignment_module_id(uuid), public.assignment_stack_id(uuid),
  public.assignment_passed(uuid, uuid), public.module_is_complete(uuid, uuid), public.module_is_unlocked(uuid, uuid),
  public.module_open_to_me(uuid), public.complete_lesson(uuid),
  public.submit_quiz(uuid, integer[]), public.submit_assignment(uuid, text, text, text),
  public.grade_submission(uuid, integer, text, boolean), public.save_quiz(uuid, jsonb),
  public.my_progress(), public.my_modules(), public.stack_roster(uuid)
to authenticated;

-- ============================== 20261102000001_exam_and_certificates.sql ==============================

-- Phase 3: final exam (server-graded), certificate eligibility, issuing, revocation and public verification.
-- A certificate can only come into existence through submit_exam() passing, and cannot be edited afterwards.

create type public.attempt_status as enum ('in_progress', 'submitted', 'expired');

-- ---------------------------------------------------------------- tables

create table public.exams (
  id uuid primary key default gen_random_uuid(),
  stack_id uuid not null unique references public.stacks (id) on delete cascade,
  title text not null default 'Final exam' check (char_length(btrim(title)) between 2 and 160),
  instructions text check (instructions is null or char_length(instructions) <= 10000),
  time_limit_minutes integer check (time_limit_minutes is null or time_limit_minutes between 1 and 600),
  pass_mark integer not null default 60 check (pass_mark between 1 and 100),
  max_attempts integer default 3 check (max_attempts is null or max_attempts between 1 and 20),
  cooldown_hours integer not null default 24 check (cooldown_hours between 0 and 720),
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger exams_touch_updated_at before update on public.exams
  for each row execute function public.touch_updated_at();

create table public.exam_questions (
  id uuid primary key default gen_random_uuid(),
  exam_id uuid not null references public.exams (id) on delete cascade,
  prompt text not null check (char_length(btrim(prompt)) between 1 and 1000),
  options jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) between 2 and 6),
  points integer not null default 1 check (points between 1 and 100),
  order_index integer not null default 0
);
create index exam_questions_exam_idx on public.exam_questions (exam_id, order_index);

create table public.exam_answer_keys (
  question_id uuid primary key references public.exam_questions (id) on delete cascade,
  correct_index integer not null check (correct_index >= 0)
);

create table public.exam_attempts (
  id uuid primary key default gen_random_uuid(),
  exam_id uuid not null references public.exams (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  attempt integer not null,
  status public.attempt_status not null default 'in_progress',
  started_at timestamptz not null default now(),
  submitted_at timestamptz,
  answers jsonb,
  score integer check (score is null or score >= 0),
  max_score integer,
  passed boolean,
  unique (exam_id, user_id, attempt)
);
create unique index exam_attempts_one_open on public.exam_attempts (exam_id, user_id) where status = 'in_progress';
create index exam_attempts_user_idx on public.exam_attempts (user_id);

create table public.certificate_signatories (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(btrim(name)) between 2 and 120),
  title text not null check (char_length(btrim(title)) between 2 and 120),
  signature_path text check (signature_path is null or char_length(signature_path) <= 300),
  display_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table public.certificates (
  id uuid primary key default gen_random_uuid(),
  certificate_no text not null unique,
  user_id uuid not null references public.profiles (id) on delete restrict,
  stack_id uuid not null references public.stacks (id) on delete restrict,
  student_name text not null,
  stack_name text not null,
  final_score integer not null,
  issued_at timestamptz not null default now(),
  signatories jsonb not null default '[]'::jsonb, -- snapshot at issue time: [{name, title, signature_path}]
  revoked_at timestamptz,
  revoked_reason text check (revoked_reason is null or char_length(revoked_reason) <= 500),
  replaced_by uuid references public.certificates (id),
  emailed_at timestamptz
);
create unique index certificates_one_active on public.certificates (user_id, stack_id) where revoked_at is null;
create index certificates_user_idx on public.certificates (user_id);

-- ---------------------------------------------------------------- helpers

create function public.exam_stack_id(p_exam_id uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select e.stack_id from public.exams e where e.id = p_exam_id;
$$;

create function public.all_modules_complete(p_user uuid, p_stack_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.modules m where m.stack_id = p_stack_id and m.is_published)
     and not exists (
       select 1 from public.modules m
       where m.stack_id = p_stack_id and m.is_published and not public.module_is_complete(p_user, m.id)
     );
$$;

create function public.exam_passed(p_user uuid, p_stack_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.exam_attempts a join public.exams e on e.id = a.exam_id
    where e.stack_id = p_stack_id and a.user_id = p_user and a.passed
  );
$$;

-- Attempts that ran past their time limit (plus a 2 minute grace) are closed as failed.
create function public.expire_stale_attempts(p_exam_id uuid, p_user uuid) returns void
language sql security definer set search_path = '' as $$
  update public.exam_attempts a
  set status = 'expired', submitted_at = a.started_at + make_interval(mins => e.time_limit_minutes),
      score = 0, max_score = null, passed = false
  from public.exams e
  where a.exam_id = e.id and a.exam_id = p_exam_id and a.user_id = p_user and a.status = 'in_progress'
    and e.time_limit_minutes is not null
    and a.started_at + make_interval(mins => e.time_limit_minutes) + interval '2 minutes' < now();
$$;

-- Students can read the questions only while they hold a running attempt.
create function public.can_read_exam_questions(p_exam_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.exam_attempts a join public.exams e on e.id = a.exam_id
    where a.exam_id = p_exam_id and a.user_id = (select auth.uid()) and a.status = 'in_progress'
      and (e.time_limit_minutes is null
           or a.started_at + make_interval(mins => e.time_limit_minutes) + interval '2 minutes' > now())
  );
$$;

create function public.ensure_exam_has_questions() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.is_published and not exists (select 1 from public.exam_questions where exam_id = new.id) then
    raise exception 'Add at least one question before publishing the exam' using errcode = 'check_violation';
  end if;
  return new;
end $$;
create trigger exams_need_questions before insert or update of is_published on public.exams
  for each row execute function public.ensure_exam_has_questions();

-- ---------------------------------------------------------------- RLS

alter table public.exams enable row level security;
alter table public.exam_questions enable row level security;
alter table public.exam_answer_keys enable row level security;
alter table public.exam_attempts enable row level security;
alter table public.certificate_signatories enable row level security;
alter table public.certificates enable row level security;

create policy "members read published exam details" on public.exams for select to authenticated
  using (is_published and (public.is_member_of(stack_id)));
create policy "leads manage their exam" on public.exams for all to authenticated
  using (public.is_lead_of(stack_id)) with check (public.is_lead_of(stack_id));
create policy "admin manages exams" on public.exams for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy "students read questions during an attempt" on public.exam_questions for select to authenticated
  using (public.can_read_exam_questions(exam_id));
create policy "leads manage exam questions" on public.exam_questions for all to authenticated
  using (public.is_lead_of(public.exam_stack_id(exam_id))) with check (public.is_lead_of(public.exam_stack_id(exam_id)));
create policy "admin manages exam questions" on public.exam_questions for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy "leads read exam keys" on public.exam_answer_keys for select to authenticated
  using (public.is_lead_of(public.exam_stack_id((select q.exam_id from public.exam_questions q where q.id = question_id))));
create policy "admin reads exam keys" on public.exam_answer_keys for select to authenticated using (public.is_admin());

create policy "own attempts" on public.exam_attempts for select to authenticated using (user_id = (select auth.uid()));
create policy "leads read their attempts" on public.exam_attempts for select to authenticated
  using (public.is_lead_of(public.exam_stack_id(exam_id)));
create policy "admin reads attempts" on public.exam_attempts for select to authenticated using (public.is_admin());

create policy "admin manages signatories" on public.certificate_signatories for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy "own certificates" on public.certificates for select to authenticated using (user_id = (select auth.uid()));
create policy "leads read their certificates" on public.certificates for select to authenticated
  using (public.is_lead_of(stack_id));
create policy "admin reads certificates" on public.certificates for select to authenticated using (public.is_admin());

revoke all on public.exams, public.exam_questions, public.exam_answer_keys, public.exam_attempts,
  public.certificate_signatories, public.certificates from anon;
-- Attempts, answer keys and certificates are only ever written by the functions below.
revoke insert, update, delete on public.exam_attempts, public.exam_answer_keys, public.certificates from authenticated;

-- ---------------------------------------------------------------- exam authoring

create function public.save_exam_questions(p_exam_id uuid, p_questions jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare q jsonb; v_id uuid; v_n integer := 0;
begin
  if not (public.is_admin() or public.is_lead_of(public.exam_stack_id(p_exam_id))) then
    raise exception 'Not allowed to edit this exam' using errcode = 'insufficient_privilege';
  end if;
  if jsonb_typeof(p_questions) <> 'array' then raise exception 'Questions must be a list' using errcode = 'check_violation'; end if;
  if exists (select 1 from public.exams where id = p_exam_id and is_published) and jsonb_array_length(p_questions) = 0 then
    raise exception 'A published exam needs at least one question' using errcode = 'check_violation';
  end if;
  delete from public.exam_questions where exam_id = p_exam_id;
  for q in select * from jsonb_array_elements(p_questions) loop
    v_n := v_n + 1;
    if (q ->> 'correct_index')::integer >= jsonb_array_length(q -> 'options') or (q ->> 'correct_index')::integer < 0 then
      raise exception 'Question % has no valid correct answer', v_n using errcode = 'check_violation';
    end if;
    insert into public.exam_questions (exam_id, prompt, options, points, order_index)
    values (p_exam_id, q ->> 'prompt', q -> 'options', coalesce((q ->> 'points')::integer, 1), v_n)
    returning id into v_id;
    insert into public.exam_answer_keys (question_id, correct_index) values (v_id, (q ->> 'correct_index')::integer);
  end loop;
end $$;

-- ---------------------------------------------------------------- taking the exam

-- The single source of truth for "where is this student with the exam".
create function public.my_exam() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  m public.stack_members; e public.exams; o public.exam_attempts;
  v_used integer; v_best integer; v_passed boolean; v_cert uuid; v_last timestamptz;
  v_state text; v_next timestamptz; v_count integer;
begin
  select * into m from public.stack_members
  where user_id = v_uid and status in ('active', 'completed')
  order by (status = 'active') desc, joined_at desc limit 1;
  if not found then return null; end if;
  select * into e from public.exams where stack_id = m.stack_id and is_published;
  if not found then return null; end if;

  perform public.expire_stale_attempts(e.id, v_uid);
  select count(*) into v_used from public.exam_attempts where exam_id = e.id and user_id = v_uid;
  select max(score * 100 / nullif(max_score, 0)) into v_best from public.exam_attempts
    where exam_id = e.id and user_id = v_uid and status = 'submitted';
  v_passed := exists (select 1 from public.exam_attempts where exam_id = e.id and user_id = v_uid and passed);
  select id into v_cert from public.certificates where user_id = v_uid and stack_id = m.stack_id and revoked_at is null;
  select * into o from public.exam_attempts where exam_id = e.id and user_id = v_uid and status = 'in_progress';
  select max(submitted_at) into v_last from public.exam_attempts where exam_id = e.id and user_id = v_uid and status <> 'in_progress';
  select count(*) into v_count from public.exam_questions where exam_id = e.id;

  if v_passed or v_cert is not null then v_state := 'passed';
  elsif o.id is not null then v_state := 'in_progress';
  elsif m.status <> 'active' or not public.all_modules_complete(v_uid, m.stack_id) then v_state := 'locked';
  elsif e.max_attempts is not null and v_used >= e.max_attempts then v_state := 'exhausted';
  elsif v_last is not null and v_last + make_interval(hours => e.cooldown_hours) > now() then
    v_state := 'cooldown'; v_next := v_last + make_interval(hours => e.cooldown_hours);
  else v_state := 'ready';
  end if;

  return jsonb_build_object(
    'exam_id', e.id, 'title', e.title, 'instructions', e.instructions,
    'time_limit_minutes', e.time_limit_minutes, 'pass_mark', e.pass_mark,
    'max_attempts', e.max_attempts, 'cooldown_hours', e.cooldown_hours, 'question_count', v_count,
    'attempts_used', v_used, 'best_score', v_best, 'passed', v_passed, 'state', v_state,
    'next_available_at', v_next, 'certificate_id', v_cert,
    'attempt_id', o.id, 'started_at', o.started_at,
    'deadline', case when o.id is not null and e.time_limit_minutes is not null
                     then o.started_at + make_interval(mins => e.time_limit_minutes) end
  );
end $$;

create function public.start_exam(p_exam_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare s jsonb; v_uid uuid := (select auth.uid()); v_attempt integer; v_id uuid;
begin
  s := public.my_exam();
  if s is null or (s ->> 'exam_id')::uuid <> p_exam_id then
    raise exception 'This exam is not available to you' using errcode = 'insufficient_privilege';
  end if;
  case s ->> 'state'
    when 'in_progress' then return s;
    when 'ready' then null;
    when 'locked' then raise exception 'Complete every module before taking the final exam' using errcode = 'check_violation';
    when 'cooldown' then raise exception 'You can try again after the waiting period' using errcode = 'check_violation';
    when 'exhausted' then raise exception 'You have used all attempts for this exam' using errcode = 'check_violation';
    else raise exception 'You have already passed this exam' using errcode = 'check_violation';
  end case;
  select coalesce(max(attempt), 0) + 1 into v_attempt from public.exam_attempts where exam_id = p_exam_id and user_id = v_uid;
  insert into public.exam_attempts (exam_id, user_id, attempt) values (p_exam_id, v_uid, v_attempt) returning id into v_id;
  return public.my_exam();
end $$;

-- Grades server-side. Returns {score, max_score, percent, passed, expired, certificate_id}.
create function public.submit_exam(p_attempt_id uuid, p_answers integer[]) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  a public.exam_attempts; e public.exams; v_uid uuid := (select auth.uid());
  v_count integer; v_total integer; v_earned integer; v_pct integer; v_passed boolean; v_cert uuid; v_deadline timestamptz;
begin
  select * into a from public.exam_attempts where id = p_attempt_id and user_id = v_uid for update;
  if not found then raise exception 'Attempt not found' using errcode = 'no_data_found'; end if;
  if a.status <> 'in_progress' then raise exception 'This attempt was already submitted' using errcode = 'check_violation'; end if;
  select * into e from public.exams where id = a.exam_id;

  if e.time_limit_minutes is not null then
    v_deadline := a.started_at + make_interval(mins => e.time_limit_minutes) + interval '2 minutes';
    if now() > v_deadline then
      update public.exam_attempts set status = 'expired', submitted_at = now(), score = 0, passed = false where id = a.id;
      return jsonb_build_object('score', 0, 'max_score', 0, 'percent', 0, 'passed', false, 'expired', true, 'certificate_id', null);
    end if;
  end if;

  select count(*), coalesce(sum(points), 0) into v_count, v_total from public.exam_questions where exam_id = e.id;
  if coalesce(array_length(p_answers, 1), 0) <> v_count then
    raise exception 'Answer every question before submitting' using errcode = 'check_violation';
  end if;
  select coalesce(sum(q.points), 0) into v_earned
  from (select id, points, row_number() over (order by order_index, id) as n from public.exam_questions where exam_id = e.id) q
  join public.exam_answer_keys k on k.question_id = q.id
  where p_answers[q.n] = k.correct_index;
  v_pct := round(v_earned * 100.0 / v_total);
  v_passed := v_pct >= e.pass_mark;

  update public.exam_attempts
  set status = 'submitted', submitted_at = now(), answers = to_jsonb(p_answers), score = v_earned, max_score = v_total, passed = v_passed
  where id = a.id;

  if v_passed then v_cert := public.issue_certificate_for(v_uid, e.stack_id); end if;
  return jsonb_build_object('score', v_earned, 'max_score', v_total, 'percent', v_pct, 'passed', v_passed,
                            'expired', false, 'certificate_id', v_cert);
end $$;

-- ---------------------------------------------------------------- certificates

create function public.new_certificate_no() returns text
language sql volatile set search_path = '' as $$
  select 'RTS-' || to_char(now(), 'YYYY') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
$$;

-- Internal: issues a certificate when, and only when, every requirement is met. Not callable by users.
create function public.issue_certificate_for(p_user uuid, p_stack_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_name text; v_stack text; v_best integer; v_sig jsonb;
begin
  if not exists (select 1 from public.stack_members where user_id = p_user and stack_id = p_stack_id and status = 'active')
     or not public.all_modules_complete(p_user, p_stack_id)
     or not public.exam_passed(p_user, p_stack_id) then
    return null;
  end if;
  select id into v_id from public.certificates where user_id = p_user and stack_id = p_stack_id and revoked_at is null;
  if v_id is not null then return v_id; end if;

  select coalesce(nullif(btrim(p.full_name), ''), p.email) into v_name from public.profiles p where p.id = p_user;
  select s.name into v_stack from public.stacks s where s.id = p_stack_id;
  select max(a.score * 100 / nullif(a.max_score, 0)) into v_best
    from public.exam_attempts a join public.exams e on e.id = a.exam_id
    where e.stack_id = p_stack_id and a.user_id = p_user and a.status = 'submitted';
  select coalesce(jsonb_agg(jsonb_build_object('name', g.name, 'title', g.title, 'signature_path', g.signature_path)
                            order by g.display_order, g.created_at), '[]'::jsonb)
    into v_sig from public.certificate_signatories g where g.is_active;

  insert into public.certificates (certificate_no, user_id, stack_id, student_name, stack_name, final_score, signatories)
  values (public.new_certificate_no(), p_user, p_stack_id, v_name, v_stack, coalesce(v_best, 0), v_sig)
  returning id into v_id;
  update public.stack_members set status = 'completed', ended_at = now()
    where user_id = p_user and stack_id = p_stack_id and status = 'active';
  perform public.write_audit('issue_certificate', 'certificate', v_id::text, jsonb_build_object('stack_id', p_stack_id));
  return v_id;
end $$;

create function public.revoke_certificate(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'Admins only' using errcode = 'insufficient_privilege'; end if;
  update public.certificates set revoked_at = now(), revoked_reason = nullif(btrim(p_reason), '')
    where id = p_id and revoked_at is null;
  if not found then raise exception 'Certificate not found or already revoked' using errcode = 'no_data_found'; end if;
  perform public.write_audit('revoke_certificate', 'certificate', p_id::text, jsonb_build_object('reason', p_reason));
end $$;

-- Replaces a certificate (e.g. after a name correction or once signatories are configured).
create function public.reissue_certificate(p_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare c public.certificates; v_new uuid; v_name text; v_sig jsonb;
begin
  if not public.is_admin() then raise exception 'Admins only' using errcode = 'insufficient_privilege'; end if;
  select * into c from public.certificates where id = p_id for update;
  if not found then raise exception 'Certificate not found' using errcode = 'no_data_found'; end if;
  select coalesce(nullif(btrim(p.full_name), ''), p.email) into v_name from public.profiles p where p.id = c.user_id;
  select coalesce(jsonb_agg(jsonb_build_object('name', g.name, 'title', g.title, 'signature_path', g.signature_path)
                            order by g.display_order, g.created_at), '[]'::jsonb)
    into v_sig from public.certificate_signatories g where g.is_active;
  if c.revoked_at is null then
    update public.certificates set revoked_at = now(), revoked_reason = 'Reissued' where id = c.id;
  end if;
  insert into public.certificates (certificate_no, user_id, stack_id, student_name, stack_name, final_score, signatories)
  values (public.new_certificate_no(), c.user_id, c.stack_id, v_name, c.stack_name, c.final_score, v_sig)
  returning id into v_new;
  update public.certificates set replaced_by = v_new where id = c.id;
  perform public.write_audit('reissue_certificate', 'certificate', v_new::text, jsonb_build_object('replaces', c.id));
  return v_new;
end $$;

-- Public verification: reveals only what is printed on the certificate, and only for an exact number.
create function public.verify_certificate(p_number text) returns table (
  certificate_no text, status text, student_name text, stack_name text, issued_at timestamptz, revoked_at timestamptz
)
language sql stable security definer set search_path = '' as $$
  select c.certificate_no, case when c.revoked_at is null then 'valid' else 'revoked' end,
         c.student_name, c.stack_name, c.issued_at, c.revoked_at
  from public.certificates c
  where c.certificate_no = upper(btrim(p_number));
$$;

-- ---------------------------------------------------------------- progress now includes the exam

create or replace function public.progress_for(p_user uuid, p_stack_id uuid) returns public.progress_summary
language plpgsql stable security definer set search_path = '' as $$
declare r public.progress_summary;
begin
  select count(*), count(c.lesson_id) into r.lessons_total, r.lessons_done
  from public.lessons l
  join public.modules m on m.id = l.module_id and m.stack_id = p_stack_id and m.is_published
  left join public.lesson_completions c on c.lesson_id = l.id and c.user_id = p_user
  where l.is_published and l.is_required;

  select count(*), count(*) filter (where public.assignment_passed(p_user, a.id)),
         coalesce(avg(coalesce((
           select max(s.score) from public.assignment_submissions s
           where s.assignment_id = a.id and s.user_id = p_user and s.status = 'graded'), 0)::numeric / a.max_score), 0)
  into r.assignments_total, r.assignments_passed, r.assignment_pct
  from public.assignments a
  join public.modules m on m.id = a.module_id and m.stack_id = p_stack_id and m.is_published
  where a.is_published;

  select coalesce(max(a.score::numeric / nullif(a.max_score, 0)), 0) into r.exam_pct
  from public.exam_attempts a join public.exams e on e.id = a.exam_id
  where e.stack_id = p_stack_id and a.user_id = p_user and a.status = 'submitted';

  r.overall := round(
    40 * case when r.lessons_total = 0 then 0 else r.lessons_done::numeric / r.lessons_total end
    + 30 * r.assignment_pct + 30 * r.exam_pct)::integer;
  -- A certified student has, by definition, met every requirement.
  if exists (select 1 from public.certificates where user_id = p_user and stack_id = p_stack_id and revoked_at is null) then
    r.overall := 100;
  end if;
  return r;
end $$;

-- ---------------------------------------------------------------- signature images (public: they print on certificates)

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('signatures', 'signatures', true, 1048576, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do nothing;

create policy "signatures: admin uploads" on storage.objects for insert to authenticated
  with check (bucket_id = 'signatures' and public.is_admin());
create policy "signatures: admin replaces" on storage.objects for update to authenticated
  using (bucket_id = 'signatures' and public.is_admin());
create policy "signatures: admin removes" on storage.objects for delete to authenticated
  using (bucket_id = 'signatures' and public.is_admin());
create policy "signatures: readable by signed-in users" on storage.objects for select to authenticated
  using (bucket_id = 'signatures');

-- ---------------------------------------------------------------- privileges
revoke execute on function
  public.exam_stack_id(uuid), public.all_modules_complete(uuid, uuid), public.exam_passed(uuid, uuid),
  public.expire_stale_attempts(uuid, uuid), public.can_read_exam_questions(uuid), public.save_exam_questions(uuid, jsonb),
  public.my_exam(), public.start_exam(uuid), public.submit_exam(uuid, integer[]), public.new_certificate_no(),
  public.issue_certificate_for(uuid, uuid), public.revoke_certificate(uuid, text), public.reissue_certificate(uuid),
  public.verify_certificate(text)
from public, anon;
grant execute on function
  public.exam_stack_id(uuid), public.all_modules_complete(uuid, uuid), public.exam_passed(uuid, uuid),
  public.can_read_exam_questions(uuid), public.save_exam_questions(uuid, jsonb), public.my_exam(),
  public.start_exam(uuid), public.submit_exam(uuid, integer[]), public.revoke_certificate(uuid, text),
  public.reissue_certificate(uuid)
to authenticated;
grant execute on function public.verify_certificate(text) to anon, authenticated;

-- ---------------------------------------------------------------- hardening: internal functions
-- Supabase grants EXECUTE on new functions to signed-in users by default, so "not granted" is not enough.
-- These helpers take a user id or write privileged data; they run only inside other security-definer
-- functions (which execute as the owner) and must never be callable directly through the API.
revoke execute on function
  public.write_audit(text, text, text, jsonb),
  public.begin_attempt(uuid, public.assignment_type),
  public.progress_for(uuid, uuid),
  public.module_is_complete(uuid, uuid),
  public.module_is_unlocked(uuid, uuid),
  public.assignment_passed(uuid, uuid),
  public.assignment_module_id(uuid),
  public.all_modules_complete(uuid, uuid),
  public.exam_passed(uuid, uuid),
  public.expire_stale_attempts(uuid, uuid),
  public.issue_certificate_for(uuid, uuid),
  public.new_certificate_no()
from authenticated, anon, public;

-- ============================== 20261103000001_privilege_hardening.sql ==============================

-- Defence in depth for table privileges.
-- Supabase grants every privilege on new public tables to anon and authenticated, relying on RLS. TRUNCATE is
-- not subject to RLS, and the REST API does not expose it, but nothing should hold it. Privileges that RLS
-- already denies are removed too, so a policy added by mistake cannot open them.

revoke truncate, references, trigger on all tables in schema public from anon, authenticated;
alter default privileges in schema public revoke truncate, references, trigger on tables from anon, authenticated;

-- Written only by security-definer functions.
revoke insert, update, delete on public.invitations, public.audit_log from authenticated;

-- ============================== 20261115000001_attempt_grants_and_profile_details.sql ==============================

-- Functional fixes before launch:
-- 1. Extra attempts. A student who used every attempt on an assignment or the final exam without passing
--    was stuck for good. The stack's leads (and admins) can now grant extra attempts, recorded in the audit log.
-- 2. Applicant details. The name and phone from the approved join application are copied to the new profile,
--    so leads see the student's phone in the roster.

-- ---------------------------------------------------------------- extra attempts

create table public.attempt_grants (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  assignment_id uuid references public.assignments (id) on delete cascade,
  exam_id uuid references public.exams (id) on delete cascade,
  extra integer not null check (extra between 1 and 10),
  reason text check (reason is null or char_length(reason) <= 500),
  granted_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  check ((assignment_id is null) <> (exam_id is null))
);
create index attempt_grants_user_idx on public.attempt_grants (user_id);

alter table public.attempt_grants enable row level security;
create policy "own grants" on public.attempt_grants for select to authenticated using (user_id = (select auth.uid()));
create policy "leads read their grants" on public.attempt_grants for select to authenticated
  using (public.is_lead_of(coalesce(public.assignment_stack_id(assignment_id), public.exam_stack_id(exam_id))));
create policy "admin reads grants" on public.attempt_grants for select to authenticated using (public.is_admin());
revoke all on public.attempt_grants from anon;
revoke insert, update, delete, truncate, references, trigger on public.attempt_grants from authenticated;

-- Internal: extra attempts granted to a user for one assignment or one exam.
create function public.extra_attempts(p_user uuid, p_assignment_id uuid, p_exam_id uuid) returns integer
language sql stable security definer set search_path = '' as $$
  select coalesce(sum(g.extra), 0)::integer from public.attempt_grants g
  where g.user_id = p_user and (g.assignment_id = p_assignment_id or g.exam_id = p_exam_id);
$$;

-- Leads of the stack (or admins) give an active student more attempts at an assignment or the exam.
create function public.grant_extra_attempts(
  p_user_id uuid, p_assignment_id uuid default null, p_exam_id uuid default null,
  p_extra integer default 1, p_reason text default null
) returns void
language plpgsql security definer set search_path = '' as $$
declare v_stack uuid;
begin
  if (p_assignment_id is null) = (p_exam_id is null) then
    raise exception 'Choose one assignment or the exam' using errcode = 'check_violation';
  end if;
  v_stack := coalesce(public.assignment_stack_id(p_assignment_id), public.exam_stack_id(p_exam_id));
  if v_stack is null then raise exception 'Not found' using errcode = 'no_data_found'; end if;
  if not (public.is_admin() or public.is_lead_of(v_stack)) then
    raise exception 'Not allowed to grant attempts in this stack' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.stack_members where user_id = p_user_id and stack_id = v_stack and status = 'active') then
    raise exception 'This student is not active in this stack' using errcode = 'check_violation';
  end if;
  if p_extra is null or p_extra not between 1 and 10 then
    raise exception 'Grant between 1 and 10 attempts' using errcode = 'check_violation';
  end if;
  insert into public.attempt_grants (user_id, assignment_id, exam_id, extra, reason, granted_by)
  values (p_user_id, p_assignment_id, p_exam_id, p_extra, nullif(btrim(p_reason), ''), (select auth.uid()));
  perform public.write_audit('grant_attempts', case when p_exam_id is null then 'assignment' else 'exam' end,
    coalesce(p_assignment_id, p_exam_id)::text,
    jsonb_build_object('user_id', p_user_id, 'stack_id', v_stack, 'extra', p_extra));
end $$;

-- Per-student attempt usage across the stack's assignments and exam, for the lead's student view.
create function public.attempt_overview(p_user_id uuid, p_stack_id uuid) returns table (
  kind text, target_id uuid, title text, module_title text,
  attempts_used integer, attempts_allowed integer, passed boolean
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (public.is_admin() or public.is_lead_of(p_stack_id)) then
    raise exception 'Not allowed to view this student' using errcode = 'insufficient_privilege';
  end if;
  return query
  select 'assignment'::text, a.id, a.title, m.title,
    (select count(*)::integer from public.assignment_submissions s where s.assignment_id = a.id and s.user_id = p_user_id),
    case when a.max_attempts is null then null else a.max_attempts + public.extra_attempts(p_user_id, a.id, null) end,
    public.assignment_passed(p_user_id, a.id)
  from public.assignments a join public.modules m on m.id = a.module_id
  where m.stack_id = p_stack_id and m.is_published and a.is_published
  union all
  select 'exam'::text, e.id, e.title, null::text,
    (select count(*)::integer from public.exam_attempts t where t.exam_id = e.id and t.user_id = p_user_id),
    case when e.max_attempts is null then null else e.max_attempts + public.extra_attempts(p_user_id, null, e.id) end,
    public.exam_passed(p_user_id, p_stack_id)
  from public.exams e
  where e.stack_id = p_stack_id and e.is_published;
end $$;

-- Assignment attempts now include granted extras.
create or replace function public.begin_attempt(p_assignment_id uuid, p_type public.assignment_type) returns integer
language plpgsql security definer set search_path = '' as $$
declare a public.assignments; v_uid uuid := (select auth.uid()); v_used integer;
begin
  select * into a from public.assignments where id = p_assignment_id and is_published and type = p_type;
  if not found then raise exception 'This assignment is not available' using errcode = 'no_data_found'; end if;
  if not public.is_active_member_of(public.assignment_stack_id(a.id)) then
    raise exception 'You are not an active member of this stack' using errcode = 'insufficient_privilege';
  end if;
  if not public.module_is_unlocked(v_uid, a.module_id) then
    raise exception 'Complete the previous module first' using errcode = 'check_violation';
  end if;
  if public.assignment_passed(v_uid, a.id) then
    raise exception 'You have already passed this assignment' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.assignment_submissions s where s.assignment_id = a.id and s.user_id = v_uid and s.status = 'submitted') then
    raise exception 'Your previous submission is still waiting to be reviewed' using errcode = 'check_violation';
  end if;
  select count(*) into v_used from public.assignment_submissions where assignment_id = a.id and user_id = v_uid;
  if a.max_attempts is not null and v_used >= a.max_attempts + public.extra_attempts(v_uid, a.id, null) then
    raise exception 'You have used all attempts for this assignment. Ask your stack lead for another attempt.'
      using errcode = 'check_violation';
  end if;
  return v_used + 1;
end $$;

-- The exam's attempt limit now includes granted extras; max_attempts in the result is the student's own limit.
create or replace function public.my_exam() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  m public.stack_members; e public.exams; o public.exam_attempts;
  v_used integer; v_best integer; v_passed boolean; v_cert uuid; v_last timestamptz;
  v_state text; v_next timestamptz; v_count integer; v_allowed integer;
begin
  select * into m from public.stack_members
  where user_id = v_uid and status in ('active', 'completed')
  order by (status = 'active') desc, joined_at desc limit 1;
  if not found then return null; end if;
  select * into e from public.exams where stack_id = m.stack_id and is_published;
  if not found then return null; end if;

  perform public.expire_stale_attempts(e.id, v_uid);
  select count(*) into v_used from public.exam_attempts where exam_id = e.id and user_id = v_uid;
  select max(score * 100 / nullif(max_score, 0)) into v_best from public.exam_attempts
    where exam_id = e.id and user_id = v_uid and status = 'submitted';
  v_passed := exists (select 1 from public.exam_attempts where exam_id = e.id and user_id = v_uid and passed);
  select id into v_cert from public.certificates where user_id = v_uid and stack_id = m.stack_id and revoked_at is null;
  select * into o from public.exam_attempts where exam_id = e.id and user_id = v_uid and status = 'in_progress';
  select max(submitted_at) into v_last from public.exam_attempts where exam_id = e.id and user_id = v_uid and status <> 'in_progress';
  select count(*) into v_count from public.exam_questions where exam_id = e.id;
  v_allowed := case when e.max_attempts is null then null else e.max_attempts + public.extra_attempts(v_uid, null, e.id) end;

  if v_passed or v_cert is not null then v_state := 'passed';
  elsif o.id is not null then v_state := 'in_progress';
  elsif m.status <> 'active' or not public.all_modules_complete(v_uid, m.stack_id) then v_state := 'locked';
  elsif v_allowed is not null and v_used >= v_allowed then v_state := 'exhausted';
  elsif v_last is not null and v_last + make_interval(hours => e.cooldown_hours) > now() then
    v_state := 'cooldown'; v_next := v_last + make_interval(hours => e.cooldown_hours);
  else v_state := 'ready';
  end if;

  return jsonb_build_object(
    'exam_id', e.id, 'title', e.title, 'instructions', e.instructions,
    'time_limit_minutes', e.time_limit_minutes, 'pass_mark', e.pass_mark,
    'max_attempts', v_allowed, 'cooldown_hours', e.cooldown_hours, 'question_count', v_count,
    'attempts_used', v_used, 'best_score', v_best, 'passed', v_passed, 'state', v_state,
    'next_available_at', v_next, 'certificate_id', v_cert,
    'attempt_id', o.id, 'started_at', o.started_at,
    'deadline', case when o.id is not null and e.time_limit_minutes is not null
                     then o.started_at + make_interval(mins => e.time_limit_minutes) end
  );
end $$;

-- ---------------------------------------------------------------- applicant details on the profile

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_email text := lower(new.email);
  v_role public.user_role;
  v_inv record;
  v_rows integer;
  v_app_name text;
  v_app_phone text;
begin
  select i.role into v_role
  from public.invitations i
  where i.email = v_email and i.status = 'pending' and i.expires_at > now()
  order by (i.role = 'stack_lead') desc, i.created_at
  limit 1;
  v_role := coalesce(v_role, 'student');

  select a.full_name, a.phone into v_app_name, v_app_phone
  from public.stack_applications a
  where a.email = v_email and a.status = 'approved'
  order by a.reviewed_at desc nulls last
  limit 1;

  insert into public.profiles (id, email, full_name, phone, role)
  values (new.id, v_email, coalesce(nullif(new.raw_user_meta_data ->> 'full_name', ''), v_app_name), v_app_phone, v_role);

  for v_inv in
    select * from public.invitations
    where email = v_email and status = 'pending' and expires_at > now() and role = v_role
    order by created_at
  loop
    if v_inv.role = 'stack_lead' then
      insert into public.stack_leads (user_id, stack_id) values (new.id, v_inv.stack_id) on conflict do nothing;
    else
      insert into public.stack_members (user_id, stack_id) values (new.id, v_inv.stack_id) on conflict do nothing;
    end if;
    get diagnostics v_rows = row_count;
    if v_rows > 0 or v_inv.role = 'stack_lead' then
      update public.invitations set status = 'accepted', accepted_at = now() where id = v_inv.id;
    end if;
  end loop;
  return new;
end $$;

-- Unchanged, except an existing student without a phone gets the one from their new application.
create or replace function public.review_application(p_application_id uuid, p_approve boolean, p_note text default null)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_app public.stack_applications;
  v_profile public.profiles;
  v_inv uuid;
begin
  select * into v_app from public.stack_applications where id = p_application_id for update;
  if not found then raise exception 'Application not found' using errcode = 'no_data_found'; end if;
  if not (public.is_admin() or public.is_lead_of(v_app.stack_id)) then
    raise exception 'Not allowed to review this application' using errcode = 'insufficient_privilege';
  end if;
  if v_app.status <> 'pending' then
    raise exception 'Application was already reviewed' using errcode = 'check_violation';
  end if;

  if p_approve then
    select * into v_profile from public.profiles where lower(email) = v_app.email;
    if found then
      if v_profile.role <> 'student' then
        raise exception 'This email belongs to a % account and cannot join as a student', v_profile.role
          using errcode = 'check_violation';
      end if;
      if exists (select 1 from public.stack_members where user_id = v_profile.id and status = 'active') then
        raise exception 'This student is already in an active stack' using errcode = 'check_violation';
      end if;
      insert into public.stack_members (user_id, stack_id) values (v_profile.id, v_app.stack_id);
      update public.profiles
      set phone = coalesce(nullif(btrim(phone), ''), v_app.phone),
          full_name = coalesce(nullif(btrim(full_name), ''), v_app.full_name)
      where id = v_profile.id;
    else
      insert into public.invitations (email, role, stack_id, invited_by)
      values (v_app.email, 'student', v_app.stack_id, (select auth.uid()))
      on conflict (email, stack_id, role) where status = 'pending' do nothing;
      select id into v_inv from public.invitations
      where email = v_app.email and stack_id = v_app.stack_id and role = 'student' and status = 'pending';
    end if;
  end if;

  update public.stack_applications
  set status = case when p_approve then 'approved'::public.application_status else 'rejected'::public.application_status end,
      reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = p_note
  where id = p_application_id;

  perform public.write_audit(case when p_approve then 'approve_application' else 'reject_application' end,
    'application', p_application_id::text, jsonb_build_object('stack_id', v_app.stack_id));
  return v_inv;
end $$;

-- ---------------------------------------------------------------- privileges
revoke execute on function public.extra_attempts(uuid, uuid, uuid) from public, anon, authenticated;
revoke execute on function
  public.grant_extra_attempts(uuid, uuid, uuid, integer, text), public.attempt_overview(uuid, uuid)
from public, anon;
grant execute on function
  public.grant_extra_attempts(uuid, uuid, uuid, integer, text), public.attempt_overview(uuid, uuid)
to authenticated;

commit;
